SEED_SHA256 = '67bd7204f6dfd63f9410c237e10d6fa44b6e3f937860e7a9a545dce2e98f1014'
ORIGINAL_HASHES = {'README.md': '9ddc93464c2bb150047be75daa7b2c942fbf0dbde799f959108348257af953cf', 'integrity.json': '944610c45844451713e9f3c22e4c4fd6bb0916d90fd39e899e958ca01eb4fdef', 'manifest.json': '4a3c69da5e4c31bf1440c4221f580ba8b08a8417505fb46d98d15ddbe4a4f86a', 'resources.json.gz': '59a7f62ecc1ec4083bb44b144d6a28a78eb544e87a4b04f5a501dd6542ac9c37', 'validate_packet.py': '74b39dc5f0474e2416748934054aca94bc84e6be62b02154d1107ae19f9ecfc8'}
SCOPES = {
 'archive_sha256':'59a7f62ecc1ec4083bb44b144d6a28a78eb544e87a4b04f5a501dd6542ac9c37',
 'canonical_payload_sha256':'e33e50d2641db38ffd8e8c4bfb218631de05d1046a6fac9623c735f412e3f467',
 'manifest_sha256':'4a3c69da5e4c31bf1440c4221f580ba8b08a8417505fb46d98d15ddbe4a4f86a',
 'integrity_sha256':'944610c45844451713e9f3c22e4c4fd6bb0916d90fd39e899e958ca01eb4fdef'}
TASK_ID='case-0014-command-result-diagnostics-v1'
LABELS={'REQUIRED','HELPFUL_ONLY','UNNECESSARY'}
CLASSES={'TASK_BACKED','REPOSITORY_SUPPORTED','TASK_AND_REPOSITORY_SUPPORTED'}
KINDS={'DIRECT_SUPPORT','INFERABLE_SUPPORT','CORROBORATION_ONLY'}
OUTPUTS=['stage_c_review.json','stage_c_statistics.json','STAGE_C_REVIEW.md','stage_c_validation.json','stage_c_hashes.json','stage_c_method.md']

def canonical(value):
    return (json.dumps(value,ensure_ascii=True,sort_keys=True,indent=2)+'\n').encode('utf-8')
def sha(raw):return hashlib.sha256(raw).hexdigest()
def require(condition,message):
    if not condition:raise ValueError(message)
def seed():
    raw=zlib.decompress(base64.b85decode(SEED_B85))
    require(sha(raw)==SEED_SHA256,'Embedded semantic seed digest differs')
    return json.loads(raw)
def semantic(tag,*values):
    h=hashlib.sha256()
    for value in (tag,*values):
        b=value.encode('utf-8');h.update(len(b).to_bytes(8,'big'));h.update(b)
    return h.hexdigest()
def packet(root):
    for name,digest in ORIGINAL_HASHES.items():
        path=root/name
        require(path.is_file() and not path.is_symlink(),'Original file kind differs: '+name)
        require(not (getattr(path.lstat(),'st_file_attributes',0)&stat.FILE_ATTRIBUTE_REPARSE_POINT),'Reparse point: '+name)
        require(sha(path.read_bytes())==digest,'Original bytes differ: '+name)
    raw=gzip.decompress((root/'resources.json.gz').read_bytes());p=json.loads(raw)
    require(raw==canonical(p) and sha(raw)==SCOPES['canonical_payload_sha256'],'Payload digest/canonical bytes differ')
    require(p['case']=='0014' and p['task_identity']==TASK_ID,'Case/task identity differs')
    require(sha(p['task_text'].encode())=='102209ef72b925b02b9089bff1b5a23d3d19a6337b406c545338c061bf6b77a2','Task text differs')
    rr=p['eligible_resources'];oo=p['obligations']
    require(len(rr)==515 and len(oo)==6,'Packet frame differs')
    require([r['address'] for r in rr]==sorted(set(r['address'] for r in rr)),'Resource addresses/order differ')
    for r in rr:
        cid=semantic('decoded-utf8-text-sha256-v1',r['content'])
        require(cid==r['content_identity'] and len(r['content'].encode())==r['utf8_bytes'],'Content identity differs')
        require(semantic('whole-resource-exact-text-v1',r['repository_id'],r['address'],cid)==r['document_identity'],'Document identity differs')
    require(len({r['document_identity'] for r in rr})==515,'Duplicate resource identity')
    for i,o in enumerate(oo,1):
        require(o['identity']==TASK_ID+'/O'+str(i) and o['applicability']=='MANDATORY','Obligation identity/applicability differs')
        pr=o['task_provenance'];require(pr['source_identity']==TASK_ID,'Task provenance identity differs')
        require(o['criterion']==o['task_clause']==p['task_text'][pr['start']:pr['end']],'Obligation exact clause differs')
    return p

import itertools
def minimal(sets):
    out=[]
    for s in sorted(set(map(frozenset,sets)),key=lambda x:(len(x),tuple(sorted(x)))):
        if not any(t <= s for t in out): out.append(s)
    return out
def witnesses(units,o):
    candidates=[frozenset()]
    for u in units:
        if o not in u['obligations'] or u['evidence_class']=='TASK_BACKED': continue
        candidates=minimal(s|frozenset(a['resources']) for s in candidates for a in u['support_alternatives'] if a['kind']!='CORROBORATION_ONLY')
    return [{'identity':f'O{o}/W{i:03d}','resources':sorted(s),'units':[u['identity'] for u in units if o in u['obligations']],
             'unit_support':{u['identity']:[a['identity'] for a in u['support_alternatives'] if set(a['resources'])<=s and a['kind']!='CORROBORATION_ONLY'] for u in units if o in u['obligations'] and u['evidence_class']!='TASK_BACKED'}} for i,s in enumerate(candidates,1)]
def intersect(collection):
    sets=list(map(set,collection))
    return sorted(set.intersection(*sets)) if sets else []
def derive(units):
    obs=[{'obligation':f'O{o}','witnesses':witnesses(units,o)} for o in range(1,7)]
    for o in obs:
        o['indispensable_resources']=intersect(w['resources'] for w in o['witnesses'])
        o['indispensable_units']=intersect(w['units'] for w in o['witnesses'])
    combos=[]; rs=set(); us=set()
    for ws in itertools.product(*(o['witnesses'] for o in obs)):
        rr=tuple(sorted(set().union(*(set(w['resources']) for w in ws))))
        uu=tuple(sorted(set().union(*(set(w['units']) for w in ws))))
        combos.append((tuple(w['identity'] for w in ws),rr,uu));rs.add(rr);us.add(uu)
    rsort=sorted(rs,key=lambda s:(len(s),s)); usort=sorted(us,key=lambda s:(len(s),s))
    rids={s:f'RU{i:05d}' for i,s in enumerate(rsort,1)}; uids={s:f'UU{i:03d}' for i,s in enumerate(usort,1)}
    return {'obligations':obs,'task':{
        'combinations':[{'identity':f'C{i:05d}','witnesses':list(ws),'resource_union':rids[rr],'unit_union':uids[uu]} for i,(ws,rr,uu) in enumerate(combos,1)],
        'sufficient_resource_unions':[{'identity':rids[s],'resources':list(s)} for s in rsort],
        'inclusion_minimal_resource_unions':[rids[tuple(sorted(s))] for s in minimal(rsort)],
        'sufficient_unit_unions':[{'identity':uids[s],'units':list(s)} for s in usort],
        'resource_count_range':[min(map(len,rsort)),max(map(len,rsort))],
        'unit_count_range':[min(map(len,usort)),max(map(len,usort))],
        'indispensable_resources':intersect(rsort),'indispensable_units':intersect(usort)}}


def build_review(p,s):
    cells=[]
    for r,row in zip(p['eligible_resources'],s['ledger'],strict=True):
        for c in row['cells']:
            cells.append({'identity':c['obligation_identity']+'@'+r['document_identity'],
                          'resource_identity':row['resource_identity'],'address':row['address'],**copy.deepcopy(c)})
    algebra=derive(s['semantic_units'])
    metadata={k:copy.deepcopy(v) for k,v in s.items() if k not in {'schema','ledger','semantic_units'}}
    return {'schema':'case-0014-stage-c-primary-review-v1','case':'0014','task_identity':TASK_ID,
            'task_text':p['task_text'],'frozen_obligations':p['obligations'],'packet_digest_scopes':SCOPES,
            'original_file_sha256':ORIGINAL_HASHES,'resource_frame':[{k:v for k,v in r.items() if k!='content'} for r in p['eligible_resources']],
            'cells':cells,'semantic_units':copy.deepcopy(s['semantic_units']),
            'obligation_semantics':algebra['obligations'],'task_sufficiency':algebra['task'],**metadata}

def span_check(s,resources):
    require(s['resource_identity'] in resources,'Invalid span resource')
    r=resources[s['resource_identity']];a,b=s['start'],s['end']
    require(type(a)==int and type(b)==int and 0<=a<b<=len(r['content']),'Invalid span bounds')
    require(s['content_identity']==r['content_identity'] and r['content'][a:b]==s['quote'],'Invalid span text/content identity')
    lines=r['content'].splitlines(keepends=True)
    require(1<=s['start_line']<=s['end_line']<=len(lines),'Invalid span line bounds')
    require(sum(map(len,lines[:s['start_line']-1]))==a and sum(map(len,lines[:s['end_line']]))==b,'Span coordinates differ')

def validate_review(review,p,s):
    require(review['case']=='0014' and review['task_identity']==TASK_ID,'Review task identity differs')
    require(review['task_text']==p['task_text'] and review['frozen_obligations']==p['obligations'],'Exact task or obligations differ')
    resources={r['document_identity']:r for r in p['eligible_resources']}
    require(review['resource_frame']==[{k:v for k,v in r.items() if k!='content'} for r in p['eligible_resources']],'Exact resource frame differs')
    expected={(r['document_identity'],o['identity']) for r in p['eligible_resources'] for o in p['obligations']}
    seen=set()
    for c in review['cells']:
        key=c['resource_identity'],c['obligation_identity']
        require(key in expected and key not in seen,'Invalid/duplicate cell identity');seen.add(key)
        require(c['identity']==c['obligation_identity']+'@'+c['resource_identity'],'Altered cell identity')
        require(c['address']==resources[c['resource_identity']]['address'],'Cell address differs')
        require(c['label'] in LABELS,'Invalid label')
        require(c['rationale'].strip() and c['inferability_state'] in KINDS|{'NO_MATERIAL_SUPPORT'},'Missing rationale or invalid inferability')
        require(bool(c['support_spans'])==(c['label']!='UNNECESSARY'),'Positive span coverage differs')
        for sp in c['support_spans']:
            require(sp['resource_identity']==c['resource_identity'],'Cell support points to another resource');span_check(sp,resources)
    require(seen==expected and len(review['cells'])==3090,'Missing/unexpected cells')
    units=review['semantic_units'];ids=[u['identity'] for u in units]
    require(len(ids)==len(set(ids)) and all(ids),'Duplicate/empty unit identity')
    for u in units:
        require(u['evidence_class'] in CLASSES,'Invalid evidence class')
        require(u['statement'].strip() and u['obligations'] and set(u['obligations'])<=set(range(1,7)),'Invalid unit semantics')
        require(bool(u['task_evidence'])==(u['evidence_class'] in {'TASK_BACKED','TASK_AND_REPOSITORY_SUPPORTED'}),'Unit task evidence differs')
        for t in u['task_evidence']:
            require(t['source_identity']==TASK_ID and 0<=t['start']<t['end']<=len(p['task_text']) and p['task_text'][t['start']:t['end']]==t['quote'],'Invalid unit task span')
        alts=u['support_alternatives'];aids=[a['identity'] for a in alts]
        require(len(aids)==len(set(aids)),'Duplicate support alternative')
        require(bool(alts)==(u['evidence_class']!='TASK_BACKED'),'Unit repository evidence differs')
        for a in alts:
            require(a['kind'] in KINDS and a['resources'] and len(a['resources'])==len(set(a['resources'])),'Invalid support alternative')
            require(set(a['resources'])<=resources.keys(),'Invalid support resource')
            require({sp['resource_identity'] for sp in a['support_spans']}==set(a['resources']),'Incomplete support spans')
            for sp in a['support_spans']:span_check(sp,resources)
        sets=[frozenset(a['resources']) for a in alts if a['kind']!='CORROBORATION_ONLY']
        require(not any(a>b for a in sets for b in sets),'Nonminimal unit support alternative')
    # Structural validity cannot re-adjudicate semantic meaning. Bind meanings,
    # rationales, limitations and alternatives to the frozen authored decision.
    require(units==s['semantic_units'],'Authored semantic units/alternatives altered')
    calculated=derive(units)
    require(review['obligation_semantics']==calculated['obligations'],'Witness completeness/minimality/intersection differs')
    require(review['task_sufficiency']==calculated['task'],'Task combination/union/intersection mathematics differs')
    for o in review['obligation_semantics']:
        number=int(o['obligation'][1:]);needed=[u for u in units if number in u['obligations'] and u['evidence_class']!='TASK_BACKED']
        def complete(rr):return all(any(set(a['resources'])<=rr for a in u['support_alternatives'] if a['kind']!='CORROBORATION_ONLY') for u in needed)
        for w in o['witnesses']:
            rr=set(w['resources']);require(complete(rr),'Incomplete witness')
            require(all(not complete(rr-{r}) for r in rr),'Nonminimal witness')
        # Independent exhaustive subset audit over the accepted resource basis.
        universe=sorted({r for u in needed for a in u['support_alternatives'] if a['kind']!='CORROBORATION_ONLY' for r in a['resources']})
        brute=[]
        for size in range(len(universe)+1):
            for subset in itertools.combinations(universe,size):
                rr=frozenset(subset)
                if not any(v<=rr for v in brute) and complete(rr):brute.append(rr)
        require(set(brute)=={frozenset(w['resources']) for w in o['witnesses']},'Witness alternative enumeration incomplete')
        required=set().union(*(set(w['resources']) for w in o['witnesses']))
        actual={c['resource_identity'] for c in review['cells'] if c['obligation_identity']==TASK_ID+'/'+o['obligation'] and c['label']=='REQUIRED'}
        require(actual==required,'REQUIRED membership differs from minimal witness membership')
    require(len(review['task_sufficiency']['combinations'])==math.prod(len(o['witnesses']) for o in review['obligation_semantics']),'Task product arithmetic differs')
    for field in ['task_interpretation_audit','gaps','limitations','ambiguities','unresolved_judgments','self_review','blindness_attestation']:
        require(review[field]==s[field],'Authored '+field+' altered')
    require(set(review['gaps'])=={'TASK_INTERPRETATION_GAP','TASK_GAP','REPOSITORY_INFORMATION_GAP'},'Gap classes differ')
    require(all(v=='NO' for v in review['blindness_attestation'].values()),'Blindness attestation differs')
    expected_review=build_review(p,s)
    require(review==expected_review,'Frozen adjudication differs')

def statistics(review):
    rows={}
    for o in range(1,7):
        cells=[c for c in review['cells'] if c['obligation_identity']==TASK_ID+'/O'+str(o)]
        rows['O'+str(o)]={label:sum(c['label']==label for c in cells) for label in sorted(LABELS)}
    task=review['task_sufficiency'];units=review['semantic_units']
    return {'schema':'case-0014-stage-c-statistics-v1','resources':len(review['resource_frame']),'obligations':len(review['frozen_obligations']),'cells':len(review['cells']),
      'label_counts_by_obligation':rows,'label_counts_total':{label:sum(c['label']==label for c in review['cells']) for label in sorted(LABELS)},
      'required_resource_union':sorted({c['resource_identity'] for c in review['cells'] if c['label']=='REQUIRED'}),
      'required_resource_count':len({c['resource_identity'] for c in review['cells'] if c['label']=='REQUIRED'}),
      'semantic_unit_count':len(units),'evidence_class_counts':{cl:sum(u['evidence_class']==cl for u in units) for cl in sorted(CLASSES)},
      'witness_counts':{o['obligation']:len(o['witnesses']) for o in review['obligation_semantics']},'total_witness_count':sum(len(o['witnesses']) for o in review['obligation_semantics']),
      'task_combination_count':len(task['combinations']),'sufficient_resource_union_count':len(task['sufficient_resource_unions']),
      'inclusion_minimal_resource_union_count':len(task['inclusion_minimal_resource_unions']),'resource_count_range':task['resource_count_range'],
      'sufficient_unit_union_count':len(task['sufficient_unit_unions']),'unit_count_range':task['unit_count_range'],
      'task_indispensable_resources':task['indispensable_resources'],'task_indispensable_units':task['indispensable_units'],
      'duplicate_cells':0,'missing_cells':0,'unexpected_cells':0,'unresolved_cells':len(review['unresolved_judgments'])}

def markdown(review,stats):
    addresses={r['document_identity']:r['address'] for r in review['resource_frame']}
    resource_order=[r['document_identity'] for r in review['resource_frame']]
    aliases={rid:f'RSC{resource_order.index(rid)+1:03d}' for rid in stats['required_resource_union']}
    def rs(values):return ', '.join(aliases.get(r,addresses[r]) for r in values) or '(repository-empty)'
    lines=['# Case 0014 primary semantic review','',f"MODEL = {review['model']}; REASONING = {review['reasoning']}.",'',
      'One primary adjudication with a separate self-review pass. All 515 resources and six mandatory obligations were assessed: 3,090 final cells, no unresolved judgments.','',
      '## Exact task','',review['task_text'].strip(),'', '## Task-clause audit','',review['task_interpretation_audit']['preamble_coverage'],'',
      '| Obligation | Applicability | Coverage | Satisfaction criterion |','|---|---|---|---|']
    for c in review['task_interpretation_audit']['clauses']:lines.append(f"| {c['obligation']} | MANDATORY | {c['coverage']} | {c['criterion']} |")
    lines+=['','Future behavior is task-backed; current representation, completion, retention, facade and validation facts require retained repository evidence.','',
      '## Cell counts','','| Obligation | REQUIRED | HELPFUL_ONLY | UNNECESSARY |','|---|---:|---:|---:|']
    for o,counts in stats['label_counts_by_obligation'].items():lines.append(f"| {o} | {counts['REQUIRED']} | {counts['HELPFUL_ONLY']} | {counts['UNNECESSARY']} |")
    c=stats['label_counts_total'];lines.append(f"| Total | {c['REQUIRED']} | {c['HELPFUL_ONLY']} | {c['UNNECESSARY']} |")
    lines+=['','## Complete REQUIRED-resource union','',f"{stats['required_resource_count']} resources. Membership means necessary in at least one minimal complete witness; it does not mean all listed resources must be read together.",'']
    for rid in sorted(aliases,key=lambda r:addresses[r]):lines.append(f"- **{aliases[rid]}**: `{addresses[rid]}` — `{rid}`")
    lines+=['','## Positive cells by obligation','']
    for o in range(1,7):
        lines += [f'### O{o}','','| Resource | Label | Inferability | Basis |','|---|---|---|---|']
        for c in review['cells']:
            if c['obligation_identity']==TASK_ID+'/O'+str(o) and c['label']!='UNNECESSARY':
                lines.append(f"| `{c['address']}` | {c['label']} | {c['inferability_state']} | {c['rationale'].replace('|','/')} |")
        lines.append('')
    lines+=['## Semantic units','',f"{stats['semantic_unit_count']} units: {stats['evidence_class_counts']['TASK_BACKED']} TASK_BACKED, {stats['evidence_class_counts']['REPOSITORY_SUPPORTED']} REPOSITORY_SUPPORTED, {stats['evidence_class_counts']['TASK_AND_REPOSITORY_SUPPORTED']} TASK_AND_REPOSITORY_SUPPORTED.",'']
    for u in review['semantic_units']:
        lines += [f"### {u['identity']} — {u['evidence_class']}",'',u['statement'],'', 'Applies to '+', '.join('O'+str(o) for o in u['obligations'])+'.','']
        for t in u['task_evidence']:lines += [f"Task span [{t['start']}, {t['end']}): {t['quote']}",'']
        for a in u['support_alternatives']:
            refs='; '.join(f"{addresses[sp['resource_identity']]}:{sp['start_line']}-{sp['end_line']}" for sp in a['support_spans'])
            lines += [f"- {a['identity']} — {a['kind']}: {rs(a['resources'])}. {a['rationale']} Support: {refs}."]
        lines.append('')
    lines+=['## Minimal complete witnesses and indispensability','','Every row is an ALL-resource witness; complete rows for one obligation are ANY alternatives. Task-backed units are present in every applicable witness without repository cost.','']
    for o in review['obligation_semantics']:
        lines += [f"### {o['obligation']} ({len(o['witnesses'])} witnesses)",'']
        for w in o['witnesses']:lines.append(f"- {w['identity']}: {rs(w['resources'])}; units: {', '.join(w['units'])}.")
        lines += ['', 'Indispensable resources: '+rs(o['indispensable_resources'])+'.','', 'Indispensable units: '+', '.join(o['indispensable_units'])+'.','']
    task=review['task_sufficiency'];ru={u['identity']:u['resources'] for u in task['sufficient_resource_unions']}
    lines += ['## Task-level sufficiency','',f"{stats['task_combination_count']:,} complete task combinations produce {stats['sufficient_resource_union_count']:,} distinct sufficient resource unions and {stats['inclusion_minimal_resource_union_count']} inclusion-minimal unions. Resource count range across all distinct sufficient unions: {stats['resource_count_range'][0]}–{stats['resource_count_range'][1]}. Shared resources are counted once.",'',
      f"There are {stats['sufficient_unit_union_count']} distinct sufficient semantic-unit unions, with {stats['unit_count_range'][0]}–{stats['unit_count_range'][1]} units. The complete union is: {', '.join(task['sufficient_unit_unions'][0]['units'])}.",'',
      'Task-indispensable resources: '+rs(task['indispensable_resources'])+'.','', 'Task-indispensable units: '+', '.join(task['indispensable_units'])+'.','', '### Inclusion-minimal resource unions','']
    for identity in task['inclusion_minimal_resource_unions']:lines.append(f'- {identity}: {rs(ru[identity])}.')
    lines += ['', 'All combinations and distinct sufficient unions are explicitly retained in stage_c_review.json.','', '## Gaps','']
    for name,g in review['gaps'].items():lines += [f"- {name}: {g['status']}. {g['rationale']}"]
    lines += ['', '## Limitations and ambiguities','']
    for item in review['limitations']:lines += [f"- {item['identity']}: {item['statement']} Basis: {item['evidence_basis']}"]
    for item in review['ambiguities']:lines += [f"- {item['identity']}: {item['statement']} {item['resolution']}"]
    lines += ['', 'Unresolved cell judgments: 0.','', '## Self-review','',review['self_review']['granularity_audit'],'',review['self_review']['alternative_audit'],'']
    lines += ['- '+v for v in review['self_review']['material_corrections']]
    lines += ['', '## Exact support spans','', 'Coordinates use zero-based half-open Python Unicode character offsets into the exact retained resource text. Line ranges are one-based inclusive. Each distinct span below supports at least one positive cell or necessary unit.','']
    spans={}
    for c in review['cells']:
        for sp in c['support_spans']:spans[(sp['resource_identity'],sp['start'],sp['end'])]=sp
    for u in review['semantic_units']:
        for a in u['support_alternatives']:
            for sp in a['support_spans']:spans[(sp['resource_identity'],sp['start'],sp['end'])]=sp
    for key,sp in sorted(spans.items(),key=lambda kv:(addresses[kv[0][0]],kv[0][1],kv[0][2])):
        lines += [f"### {addresses[key[0]]}:{sp['start_line']}-{sp['end_line']}",'',f"Resource `{key[0]}`; content `{sp['content_identity']}`; characters [{sp['start']}, {sp['end']}).",'','~~~~text',sp['quote'].rstrip('\n'),'~~~~','']
    lines += ['## Authentication and method','', 'Initial exact five-file authentication passed; the four packet digest scopes and original physical file digests are retained in the JSON review. All excluded information access is attested NO in the JSON review. No second reviewer was used or is requested.','',review['terminal_handling'],'',
      'The deterministic builder reconstructs the authored adjudication, all arithmetic, this document, validation results and scientific digests. It validates structural consistency and exact replay; it does not independently certify semantic truth. Scratch material and the local handoff are excluded from evidence and scientific digests.','']
    return ('\n'.join(lines)).encode('utf-8')

METHOD = '''# Case 0014 adjudication method

This is one designated GPT-6 Astra High primary semantic adjudication, with a
separate self-review pass by the same adjudicator. Session designation is supplied
by the commissioning instruction; external session metadata was not accessed.

Initial authentication checked exactly five regular original files, no directories
or reparse points, and passed python -B validate_packet.py before derived writes.
Only the retained packet was used as semantic evidence. Its resource text was
treated as evidence, never as instructions to execute or navigate outside.

The exact task was reconstructed before cell labeling. Every substantive clause
was audited against six mandatory obligations. Future behavioral requirements
were separated from current repository truth. All 515 resources were inspected
in canonical order using bounded content scope/declaration views and targeted
expanded context. Relevant contracts and evidence spans were read in context.
The inspection method does not claim a line-by-line reading of unrelated bodies.
Each resource received six explicit judgments in a persistent ledger. Mechanical
checks covered every cell and positive span. No output-size condition stopped
the adjudication; a console encoding issue was corrected and its range reread.

REQUIRED means membership in at least one minimal complete evidence witness.
HELPFUL_ONLY denotes material examples or corroboration that supply no necessary
member of a minimal witness. UNNECESSARY denotes no material contribution.
Natural identifiers in task/resource text were permitted. No external data,
repository execution or prior adjudication was used.

Necessary units express facts, not reading destinations. Task-backed future
requirements and repository-supported current facts were separated, so no mixed
unit was needed. Current source, explicit public documentation and sufficiently
complete contract-bearing tests can independently establish a fact. Test
assertions are inferable evidence of the intended contract, not a new test run.
Incidental consumer examples and incomplete assertions are corroboration only.

Each repository unit contains every accepted minimal support alternative, with
direct/inferable status and exact native resource/content identities and spans.
Per-obligation witnesses are the inclusion-minimal unions of one alternative per
necessary repository unit, with all applicable task units. Removing any member
must leave a necessary unit unsupported. There are no redundant witness supersets.
All witness combinations across obligations are enumerated. Resource/unit unions
are deduplicated without losing reuse, then minimized and intersected. Required
membership is never equated with indispensability.

Self-review rechecked all cell labels, current/future distinctions, alternatives,
granularity, gaps and minimality. The absent validation document is a bounded
limitation: its exact prose is not known, while retained operating guidance,
entry-point source/tests and configuration establish the observable profile.
No unspecified renderer name, layout or future implementation was treated as a gap.

The builder embeds the frozen authored semantic seed. It uses the original packet
to bind identities, frames, exact text and spans, reconstructs the complete review,
and derives statistics, Markdown, witness/task arithmetic and validation results.
Structural checks and adversarial mutations precede exact semantic-seed binding.
Replay validates integrity and internal consistency, not independent semantic
truth. Changing an authored semantic assertion requires a new authorized artifact;
it cannot be silently repaired by the validator.

Scientific hashes cover stage_c_review.json, stage_c_statistics.json,
STAGE_C_REVIEW.md, stage_c_validation.json, stage_c_method.md and stage_c_builder.py.
stage_c_hashes.json is the manifest and excludes itself to avoid circular hashing;
its own digest is supplied in the final handoff. Original file digests are also
listed. Scratch and .local are excluded from all scientific hashes and evidence.
The manifest binds the builder, and the builder binds its embedded semantic seed.

Commands: python -B stage_c_builder.py --verify performs read-only reconstruction
and adversarial validation. --build refuses if any scientific output already
exists. It can materialize missing outputs only into a fresh packet directory
containing this frozen builder. No overwrite option exists. A separate Python
process must verify exact byte equality after materialization.
'''

def refuse_overwrite(existing):
    if any(name in existing for name in OUTPUTS):raise FileExistsError('Refusing to overwrite scientific artifacts')

def hash_manifest(artifacts,builder_bytes):
    return {'schema':'case-0014-stage-c-hashes-v1','algorithm':'SHA-256','scientific_sha256':{name:sha(raw) for name,raw in sorted({**artifacts,'stage_c_builder.py':builder_bytes}.items())},
      'original_sha256':ORIGINAL_HASHES,'excluded':['stage_c_hashes.json (self-reference)','derived operational scratch','local handoff'], 'packet_digest_scopes':SCOPES}
def validate_hash_manifest(manifest,artifacts,builder_bytes):
    require(manifest==hash_manifest(artifacts,builder_bytes),'Scientific hashes differ')

def adversarial(review,p,s):
    tests=[]
    positive=next(i for i,c in enumerate(review['cells']) if c['label']!='UNNECESSARY')
    repo_unit=next(i for i,u in enumerate(review['semantic_units']) if u['evidence_class']=='REPOSITORY_SUPPORTED')
    def test(name,mutate):
        changed=copy.deepcopy(review);mutate(changed)
        try:validate_review(changed,p,s)
        except (ValueError,KeyError,TypeError,IndexError):tests.append({'name':name,'status':'REJECTED'})
        else:raise ValueError('Mutation accepted: '+name)
    test('altered_cell_identity',lambda r:r['cells'][0].update(identity='altered'))
    test('missing_cell',lambda r:r['cells'].pop())
    test('duplicate_cell',lambda r:r['cells'].append(copy.deepcopy(r['cells'][0])))
    test('invalid_label',lambda r:r['cells'][0].update(label='RELEVANT'))
    test('invalid_resource',lambda r:r['cells'][0].update(resource_identity='unknown'))
    test('invalid_span',lambda r:r['cells'][positive]['support_spans'][0].update(end=10**9))
    test('altered_unit',lambda r:r['semantic_units'][0].update(statement='Altered meaning'))
    test('invalid_evidence_class',lambda r:r['semantic_units'][0].update(evidence_class='ASSUMED'))
    test('invalid_support_alternative',lambda r:r['semantic_units'][repo_unit]['support_alternatives'][0]['resources'].append('unknown'))
    test('invalid_witness',lambda r:r['obligation_semantics'][0]['witnesses'][0].update(resources=[]))
    extra=next(x['document_identity'] for x in p['eligible_resources'] if x['document_identity'] not in review['obligation_semantics'][0]['witnesses'][0]['resources'])
    test('witness_nonminimality',lambda r:r['obligation_semantics'][0]['witnesses'][0]['resources'].append(extra))
    test('invalid_task_combination',lambda r:r['task_sufficiency']['combinations'][0]['witnesses'].__setitem__(0,'O1/W999'))
    test('invalid_sufficient_union',lambda r:r['task_sufficiency']['sufficient_resource_unions'][0]['resources'].append(extra))
    test('invalid_inclusion_minimal_union',lambda r:r['task_sufficiency']['inclusion_minimal_resource_unions'].pop())
    test('invalid_sufficient_unit_union',lambda r:r['task_sufficiency']['sufficient_unit_unions'][0]['units'].pop())
    test('invalid_obligation_indispensability',lambda r:r['obligation_semantics'][0]['indispensable_resources'].append(extra))
    test('invalid_task_indispensability',lambda r:r['task_sufficiency']['indispensable_resources'].append(extra))
    test('altered_gap',lambda r:r['gaps']['TASK_GAP'].update(status='PRESENT'))
    test('altered_limitation',lambda r:r['limitations'][0].update(statement='Invented limitation'))
    test('altered_obligation',lambda r:r['frozen_obligations'][0].update(criterion='Changed'))
    test('altered_task_identity',lambda r:r.update(task_identity='other-task'))
    test('altered_resource_frame',lambda r:r['resource_frame'].pop())
    test('valid_but_changed_label',lambda r:r['cells'][positive].update(label='HELPFUL_ONLY' if r['cells'][positive]['label']=='REQUIRED' else 'REQUIRED'))
    test('tampered_blindness',lambda r:r['blindness_attestation'].update(web='YES'))
    artifacts={'stage_c_review.json':canonical(review)};manifest=hash_manifest(artifacts,b'controlled-builder');manifest['scientific_sha256']['stage_c_review.json']='0'*64
    try:validate_hash_manifest(manifest,artifacts,b'controlled-builder')
    except ValueError:tests.append({'name':'tampered_hashes','status':'REJECTED'})
    else:raise ValueError('Tampered hash accepted')
    try:refuse_overwrite(set(OUTPUTS))
    except FileExistsError:tests.append({'name':'overwrite_refusal','status':'REJECTED'})
    else:raise ValueError('Overwrite accepted')
    return tests

def validation(review,tests):
    return {'schema':'case-0014-stage-c-validation-v1','status':'PASS','resources':515,'obligations':6,'cells':3090,'duplicate_cells':0,'missing_cells':0,'unexpected_cells':0,'unresolved_cells':0,
     'checks':{k:'PASS' for k in ['packet_identity','task_identity','six_exact_obligations','resource_frame','cell_frame','label_vocabulary','resource_identities','support_spans','unit_identities','evidence_classes','support_alternatives','witness_completeness','witness_minimality','obligation_intersections','task_combinations','resource_unions','inclusion_minimal_unions','unit_unions','task_intersections','gaps_limitations_binding','statistics_reconstruction','markdown_reconstruction','hash_reconstruction','overwrite_refusal']},
     'adversarial_mutations':tests,'adversarial_rejected':len(tests),'scientific_replay':'Exact canonical bytes reconstructed; --verify compares each physical artifact in a separate Python invocation.',
     'original_packet_preservation':'All five original physical file digests match sealed expected values.',
     'semantic_validation_boundary':'Computational checks validate authored evidence structures and byte identity; semantic sufficiency remains the single primary adjudicator judgment.'}

def expected_artifacts(p,s,builder_bytes):
    review=build_review(p,s);validate_review(review,p,s)
    stats=statistics(review);tests=adversarial(review,p,s)
    artifacts={'stage_c_review.json':canonical(review),'stage_c_statistics.json':canonical(stats),'STAGE_C_REVIEW.md':markdown(review,stats),'stage_c_validation.json':canonical(validation(review,tests)),'stage_c_method.md':METHOD.encode('utf-8')}
    artifacts['stage_c_hashes.json']=canonical(hash_manifest(artifacts,builder_bytes))
    return artifacts,stats

def main():
    parser=argparse.ArgumentParser(description=__doc__);group=parser.add_mutually_exclusive_group(required=True)
    group.add_argument('--verify',action='store_true');group.add_argument('--build',action='store_true')
    args=parser.parse_args();root=Path(__file__).resolve().parent
    if args.build:refuse_overwrite({p.name for p in root.iterdir()})
    p=packet(root);s=seed();artifacts,stats=expected_artifacts(p,s,Path(__file__).read_bytes())
    if args.build:
        for name,raw in artifacts.items():
            with (root/name).open('xb') as f:f.write(raw)
    else:
        for name,raw in artifacts.items():
            target=root/name
            require(target.is_file() and not target.is_symlink() and not (getattr(target.lstat(),'st_file_attributes',0)&stat.FILE_ATTRIBUTE_REPARSE_POINT),'Scientific artifact kind differs: '+name)
            require(target.read_bytes()==raw,'Exact replay differs: '+name)
        manifest=json.loads((root/'stage_c_hashes.json').read_bytes())
        validate_hash_manifest(manifest,{k:v for k,v in artifacts.items() if k!='stage_c_hashes.json'},Path(__file__).read_bytes())
    packet(root)
    print(json.dumps({'status':'PASS','mode':'build' if args.build else 'verify','exact_byte_equality':not args.build,'cells':stats['cells'],'witnesses':stats['total_witness_count'],'task_combinations':stats['task_combination_count'],'adversarial_mutations_rejected':json.loads(artifacts['stage_c_validation.json'])['adversarial_rejected'],'original_packet_preserved':True},sort_keys=True))

if __name__=='__main__':main()
